{'code': "from qgis.core import QgsApplication, QgsProcessingParameterEnum
alg = QgsApplication.processingRegistry().algorithmById('pdal:compare')
if alg is None:
    result = 'NOT FOUND'
else:
    params = []
    for p in alg.parameterDefinitions():
        entry = {'name': p.name(), 'desc': p.description(), 'type': p.type(), 'default': p.defaultValue()}
        if isinstance(p, QgsProcessingParameterEnum):
            entry['options'] = p.options()
        params.append(entry)
    result = {
        'id': alg.id(),
        'displayName': alg.displayName(),
        'group': alg.group(),
        'provider': alg.provider().name() if alg.provider() else None,
        'shortHelp': alg.shortHelpString(),
        'params': params,
        'outputs': [{'name': o.name(), 'desc': o.description(), 'type': o.type()} for o in alg.outputDefinitions()],
    }"}
